 1→import { ChangeDetectionStrategy, Component, inject, InjectionToken, LOCALE_ID, signal } from '@angular/core';
 2→import { DOCUMENT } from '@angular/common';
 3→import { RouterLink } from '@angular/router';
 4→import { ThemeService } from '../theme';
 5→
 6→const LANGUAGES = ['NL', 'DE', 'EN'] as const;
 7→const VALID_LOCALES = ['en', 'nl', 'de'] as const;
 8→
 9→const LOCALE_TO_LANGUAGE: Record<string, string> = {
10→  en: 'EN',
11→  nl: 'NL',
12→  de: 'DE',
13→};
14→
15→/**
16→ * Injectable function for navigating to a URL.
17→ * Abstracted to allow easy testing without jsdom location restrictions.
18→ */
19→export type NavigateFn = (url: string) => void;
20→
21→export const NAVIGATE_FN = new InjectionToken<NavigateFn>('NavigateFn', {
22→  providedIn: 'root',
23→  factory: () => {
24→    const doc = inject(DOCUMENT);
25→    return (url: string) => {
26→      const window = doc.defaultView;
27→      if (window) {
28→        window.location.href = url;
29→      }
30→    };
31→  },
32→});
33→
34→@Component({
35→  selector: 'app-header',
36→  imports: [RouterLink],
37→  templateUrl: './header.html',
38→  styleUrl: './header.scss',
39→  changeDetection: ChangeDetectionStrategy.OnPush,
40→})
41→export class HeaderComponent {
42→  protected readonly themeService = inject(ThemeService);
43→  protected readonly isDark = this.themeService.isDarkMode;
44→  protected readonly languages = LANGUAGES;
45→
46→  private readonly localeId = inject(LOCALE_ID);
47→  private readonly document = inject(DOCUMENT);
48→  private readonly navigate = inject(NAVIGATE_FN);
49→
50→  protected readonly activeLanguage = signal<string>(
51→    LOCALE_TO_LANGUAGE[this.localeId] ?? 'EN',
52→  );
53→
54→  selectLanguage(lang: string): void {
55→    const targetLocale = lang.toLowerCase();
56→
57→    // Validate against known locale set to prevent open redirects
58→    if (!VALID_LOCALES.includes(targetLocale as typeof VALID_LOCALES[number])) {
59→      return;
60→    }
61→
62→    const currentLocale = this.localeId.toLowerCase();
63→
64→    if (targetLocale === currentLocale) {
65→      return;
66→    }
67→
68→    const window = this.document.defaultView;
69→    if (!window) {
70→      return;
71→    }
72→
73→    // Get the current path without the locale prefix
74→    const currentPath = window.location.pathname;
75→    const pathWithoutLocale = currentPath.replace(/^\/(en|nl|de)(\/|$)/, '/');
76→    const newPath = `/${targetLocale}${pathWithoutLocale === '/' ? '/' : pathWithoutLocale}`;
77→
78→    this.navigate(newPath);
79→  }
80→}
