 1→/**
 2→ * i18n E2E tests for language switching.
 3→ *
 4→ * Convention: this file's name must contain "language-switching" so that
 5→ * the "i18n" project in playwright.config.ts picks it up via testMatch.
 6→ * These tests run against the multi-locale static server on port 4201
 7→ * (serve-i18n.mjs), NOT the default dev server on port 4200.
 8→ */
 9→import { test, expect } from '@playwright/test';
10→
11→test.describe('Language switching shows translations in NL, DE, EN', () => {
12→  test('should display English text by default and switch to Dutch and German', async ({ page }) => {
13→    // Start on the English homepage
14→    await page.goto('/en/');
15→
16→    // Verify English content is displayed
17→    const heroTagline = page.getByTestId('hero-tagline');
18→    await expect(heroTagline).toBeVisible();
19→    await expect(heroTagline).toContainText('Free, ad-free, gamified guitar training');
20→
21→    const ctaButton = page.getByTestId('cta-learn');
22→    await expect(ctaButton).toContainText('Start Learning');
23→
24→    const navHome = page.getByTestId('nav-home');
25→    await expect(navHome).toContainText('Home');
26→
27→    const navLearn = page.getByTestId('nav-learn');
28→    await expect(navLearn).toContainText('Learn');
29→
30→    // Switch to Dutch by clicking the NL language option
31→    const languageSelector = page.getByTestId('language-selector');
32→    await expect(languageSelector).toBeVisible();
33→
34→    const nlButton = languageSelector.getByTestId('language-option').filter({ hasText: 'NL' });
35→    await nlButton.click();
36→
37→    // Should navigate to the Dutch locale
38→    await expect(page).toHaveURL(/\/nl\//);
39→
40→    // Verify Dutch content is displayed
41→    await expect(page.getByTestId('hero-tagline')).toContainText('Gratis, zonder reclame, gegamificeerde gitaartraining');
42→    await expect(page.getByTestId('cta-learn')).toContainText('Begin met leren');
43→    await expect(page.getByTestId('nav-home')).toContainText('Home');
44→    await expect(page.getByTestId('nav-learn')).toContainText('Leren');
45→
46→    // Switch to German by clicking the DE language option
47→    const deButton = page.getByTestId('language-selector').getByTestId('language-option').filter({ hasText: 'DE' });
48→    await deButton.click();
49→
50→    // Should navigate to the German locale
51→    await expect(page).toHaveURL(/\/de\//);
52→
53→    // Verify German content is displayed
54→    await expect(page.getByTestId('hero-tagline')).toContainText('Kostenlos, werbefrei, spielerisches Gitarrentraining');
55→    await expect(page.getByTestId('cta-learn')).toContainText('Jetzt loslegen');
56→    await expect(page.getByTestId('nav-home')).toContainText('Startseite');
57→    await expect(page.getByTestId('nav-learn')).toContainText('Lernen');
58→
59→    // Switch back to English
60→    const enButton = page.getByTestId('language-selector').getByTestId('language-option').filter({ hasText: 'EN' });
61→    await enButton.click();
62→
63→    // Should navigate back to the English locale
64→    await expect(page).toHaveURL(/\/en\//);
65→
66→    // Verify English content is restored
67→    await expect(page.getByTestId('hero-tagline')).toContainText('Free, ad-free, gamified guitar training');
68→    await expect(page.getByTestId('cta-learn')).toContainText('Start Learning');
69→  });
