34→@Component({
35→  selector: 'app-header',
36→  imports: [RouterLink],
37→  templateUrl: './header.html',
38→  styleUrl: './header.scss',
39→  changeDetection: ChangeDetectionStrategy.OnPush,
40→})
41→export class HeaderComponent {
42→  protected readonly themeService = inject(ThemeService);
43→  protected readonly isDark = this.themeService.isDarkMode;
44→  protected readonly languages = LANGUAGES;
45→
46→  protected readonly themeToggleLabel = computed(() =>
47→    this.isDark()
48→      ? $localize`:Theme toggle aria label for switching to light@@header.themeToggle.lightLabel:Switch to light theme`
49→      : $localize`:Theme toggle aria label for switching to dark@@header.themeToggle.darkLabel:Switch to dark theme`,
50→  );
51→
52→  private readonly localeId = inject(LOCALE_ID);
53→  private readonly document = inject(DOCUMENT);
54→  private readonly navigate = inject(NAVIGATE_FN);
55→
56→  protected readonly activeLanguage = signal<string>(
57→    LOCALE_TO_LANGUAGE[this.localeId] ?? 'EN',
58→  );
59→
60→  selectLanguage(lang: string): void {
61→    const targetLocale = lang.toLowerCase();
62→
63→    // Validate against known locale set to prevent open redirects
64→    if (!VALID_LOCALES.includes(targetLocale as typeof VALID_LOCALES[number])) {
65→      return;
66→    }
67→
68→    const currentLocale = this.localeId.toLowerCase();
69→
70→    if (targetLocale === currentLocale) {
71→      return;
72→    }
73→
74→    const window = this.document.defaultView;
75→    if (!window) {
76→      return;
77→    }
78→
79→    // Get the current path without the locale prefix
80→    const currentPath = window.location.pathname;
81→    const pathWithoutLocale = currentPath.replace(/^\/(en|nl|de)(\/|$)/, '/');
82→    const newPath = `/${targetLocale}${pathWithoutLocale === '/' ? '/' : pathWithoutLocale}`;
83→
84→    this.navigate(newPath);
85→  }
86→}
